using Exceptionless;

var builder = WebApplication.CreateBuilder(args);
builder.AddExceptionless("YOUR_API_KEY");
builder.Services.AddProblemDetails();

var app = builder.Build();
app.UseExceptionHandler();
app.UseExceptionless();

app.Run();

using Exceptionless;

ExceptionlessClient.Default.Startup("YOUR_API_KEY");

try
{
    throw new InvalidOperationException("Order 1234 could not be submitted");
}
catch (Exception ex)
{
    ex.ToExceptionless()
        .SetProperty("OrderId", 1234)
        .AddTags("checkout")
        .MarkAsCritical()
        .Submit();
}

import { Exceptionless } from "@exceptionless/browser";

await Exceptionless.startup("YOUR_API_KEY");

// Unhandled errors are captured automatically.
// Track the things you care about, too:
await Exceptionless.submitFeatureUsage("Checkout");

import { Exceptionless } from "@exceptionless/node";

await Exceptionless.startup("YOUR_API_KEY");

try {
  throw new Error("Orders import failed");
} catch (error) {
  await Exceptionless.submitException(error);
}

import { Exceptionless } from "@exceptionless/react-native";

await Exceptionless.startup((c) => {
  c.apiKey = "YOUR_API_KEY";
});

// JavaScript errors and promise rejections are captured automatically.
await Exceptionless.submitFeatureUsage("Checkout");
